import { createHash } from "node:crypto";
import { z } from "zod";
import {
  type ProductScope,
  type ResearchDataset,
  type ResearchRecord,
  type Source,
  type LlmClient,
} from "@reqflow/core";
import { BMW_FEEDBACK_HEADERS, type ResearchTableRow } from "./tabular";
export { BMW_FEEDBACK_HEADERS };

export const SummarizedFeedbackItem = z
  .object({
    brand: z.string().trim().min(1).default("[BMW]"),
    salesDescription: z.string().trim().min(1).default("[BMW 1 Series]"),
    country: z.string().trim().min(1).default("EU"),
    derivate: z.string().trim().min(1).default("F70"),
    engineType: z.enum(["ICE", "BEV", "PHEV", "unknown"]).default("ICE"),
    feedbackType: z.enum(["Likes", "Wants", "Defect", "Difficult to Use"]).default("Likes"),
    summary: z.string().trim().min(1),
    vfcLevel2Name: z.string().trim().min(1),
    vfcLevel3Name: z.string().trim().min(1),
  })
  .strict();

export type SummarizedFeedbackItem = z.infer<typeof SummarizedFeedbackItem>;

export const SourceSummariesResult = z
  .object({
    items: z.array(SummarizedFeedbackItem).min(1).max(5),
  })
  .strict();

export type SourceSummariesResult = z.infer<typeof SourceSummariesResult>;

export function defaultDerivate(model: string): string {
  if (/1\s*series|1er|f70/i.test(model)) return "F70";
  if (/5\s*series|5er|g60/i.test(model)) return "G60";
  if (/7\s*series|7er|g70/i.test(model)) return "G70";
  return "F70";
}

export function defaultSalesDescription(model: string): string {
  if (/1\s*series|1er|f70/i.test(model)) return "[BMW 1 Series]";
  if (/5\s*series|5er|g60/i.test(model)) return "[BMW 5 Series]";
  if (/7\s*series|7er|g70/i.test(model)) return "[BMW 7 Series]";
  return `[BMW ${model || "1 Series"}]`;
}

export const SUMMARIZER_SYSTEM = [
  "You are the BMW Research Summarizer and Feedback Analyst for product decision making.",
  "Your task is to analyze external research content (road tests, owner reviews, equipment lists, competitor benchmarks, forum discussions) and convert it into structured BMW-compatible feedback entries.",
  "For each distinct substantive key topic covered in the source:",
  "1. Write an extensive, articulate summary ('summary') covering all key findings, user impressions, complaints, praise, or technical equipment details.",
  "   - The summary should be thorough (2 to 6 sentences), capturing the substance and nuances of the source.",
  "2. Assign accurate BMW feedback attributes:",
  "   - brand: '[BMW]' or competitor in brackets if a competing vehicle is evaluated (e.g. '[Audi]', '[Mercedes]', '[Volkswagen]')",
  "   - salesDescription: vehicle model in brackets (e.g. '[BMW 1 Series]', '[BMW 5 Series]', '[BMW 7 Series]')",
  "   - country: ISO country code or region (e.g. 'DE', 'EU', 'US', 'GB', 'JP', 'CN')",
  "   - derivate: vehicle code (e.g. 'F70', 'G60', 'G70')",
  "   - engineType: 'ICE' (petrol/diesel), 'BEV' (electric/i5/i7), 'PHEV' (plug-in hybrid), or 'unknown'",
  "   - feedbackType: 'Likes' (praise/strength), 'Wants' (feature request/wish), 'Defect' (malfunction/bug), or 'Difficult to Use' (usability issue/ergonomics)",
  "   - vfcLevel2Name: BMW Level 2 classification (e.g. 'ConnectedDrive and Infotainment, overall technology', 'Drive, driving dynamics and chassis, overall technology', 'Seats', 'Handling / Riding', 'Drivetrain', 'Touch screen, operation', 'Exterior design', 'Interior design', 'Driver Assistance Systems', 'Comfort Access', 'Audio mode, sound')",
  "   - vfcLevel3Name: BMW Level 3 classification (e.g. 'Like: function', 'Not user-friendly', 'Customer request: usability', 'Customer request: function', 'Malfunction', 'Likes comfort', 'Like: performance', 'Look / design appeals')",
  "Return 1 to 5 structured items per source.",
].join("\n");

/** Rule-based offline fallback for tests and offline mock mode. */
export function offlineSummarizeRecord(
  record: ResearchRecord,
  source: Source | undefined,
  scope: ProductScope,
): SummarizedFeedbackItem {
  const text = record.text.trim();
  const lower = text.toLowerCase();
  const vehicle = scope.vehicleLine || scope.vehicleCode || "1 Series";
  const derivate = defaultDerivate(vehicle);
  const salesDesc = defaultSalesDescription(vehicle);
  const country =
    typeof record.fields?.Country === "string"
      ? record.fields.Country
      : (record.marketAttribution?.value ?? scope.market ?? "EU");

  let feedbackType: SummarizedFeedbackItem["feedbackType"] = "Likes";
  if (/\b(defect|broken|fault|error|malfunction|damage|squeak|rattle)\b/i.test(lower)) {
    feedbackType = "Defect";
  } else if (
    /\b(difficult|awkward|distract|hard|complicated|annoy|confusing|frustrat|nightmare)\b/i.test(
      lower,
    )
  ) {
    feedbackType = "Difficult to Use";
  } else if (/\b(wish|want|need|missing|lack|should have|wants|request)\b/i.test(lower)) {
    feedbackType = "Wants";
  }

  let vfcLevel2 = "General enquiry: customer feedback";
  let vfcLevel3 = "Like: function";

  if (/\b(touchscreen|touch|display|screen|idrive|software|navi|app|os9|os8|infotainment|bluetooth)\b/i.test(lower)) {
    vfcLevel2 = "ConnectedDrive and Infotainment, overall technology";
    vfcLevel3 =
      feedbackType === "Difficult to Use"
        ? "Not user-friendly"
        : feedbackType === "Defect"
          ? "Malfunction"
          : feedbackType === "Wants"
            ? "Customer request: usability"
            : "Like: function";
  } else if (/\b(seat|seating|chair|lumbar|sitz)\b/i.test(lower)) {
    vfcLevel2 = "Seats";
    vfcLevel3 =
      feedbackType === "Difficult to Use"
        ? "Not user-friendly"
        : feedbackType === "Likes"
          ? "Likes comfort"
          : "Customer request: function";
  } else if (/\b(steer|suspension|corner|ride|chassis|fahrwerk|handling|nimble|stability)\b/i.test(lower)) {
    vfcLevel2 = "Handling / Riding";
    vfcLevel3 = "Like: performance";
  } else if (/\b(engine|motor|hybrid|power|drivetrain|gearbox|transmission|mild hybrid|consumption|efficiency)\b/i.test(lower)) {
    vfcLevel2 = "Drivetrain";
    vfcLevel3 = "Like: performance";
  } else if (/\b(brake|braking|bremse)\b/i.test(lower)) {
    vfcLevel2 = "Braking";
    vfcLevel3 = feedbackType === "Defect" ? "Malfunction" : "Like: function";
  } else if (/\b(assist|speed limit|parking|lane|kamera|sensor)\b/i.test(lower)) {
    vfcLevel2 = "Driver Assistance Systems";
    vfcLevel3 = feedbackType === "Defect" ? "Malfunction" : "Like: function";
  } else if (/\b(interior|cabin|materials|plastic|quality|verarbeitung)\b/i.test(lower)) {
    vfcLevel2 = "Interior design";
    vfcLevel3 = "Look / design appeals";
  } else if (/\b(exterior|styling|front|rear|grille|look)\b/i.test(lower)) {
    vfcLevel2 = "Exterior design";
    vfcLevel3 = "Look / design appeals";
  }

  const cleanText = text.replace(/[\r\n]+/g, " ").trim();
  const summaryPrefix = source?.publisher || source?.title ? `${source?.publisher || source?.title}: ` : "";
  const excerpt = cleanText.slice(0, 350) + (cleanText.length > 350 ? "…" : "");
  const summary = `[Summary] ${summaryPrefix}${excerpt}`;

  let engineType: SummarizedFeedbackItem["engineType"] = "ICE";
  if (/\b(bev|electric|vollelektrisch|i5|i7|battery|laden|charging)\b/i.test(lower)) {
    engineType = "BEV";
  } else if (/\b(phev|plug-in|hybrid)\b/i.test(lower)) {
    engineType = "PHEV";
  }

  return {
    brand: "[BMW]",
    salesDescription: salesDesc,
    country,
    derivate,
    engineType,
    feedbackType,
    summary,
    vfcLevel2Name: vfcLevel2,
    vfcLevel3Name: vfcLevel3,
  };
}

/** Runs work across items with a concurrency cap, settling all or aborting promptly. */
export async function parallelMap<T, R>(
  items: readonly T[],
  concurrency: number,
  fn: (item: T, index: number) => Promise<R>,
  signal: AbortSignal,
): Promise<R[]> {
  const results: R[] = new Array(items.length);
  let next = 0;
  async function worker() {
    while (next < items.length) {
      if (signal.aborted) throw new Error("Operation cancelled.");
      const current = next++;
      results[current] = await fn(items[current]!, current);
    }
  }
  const workers = Math.max(1, Math.min(concurrency, items.length));
  await Promise.all(Array.from({ length: workers }, worker));
  return results;
}

export interface SummarizeOptions {
  llm?: LlmClient;
  scope: ProductScope;
  signal: AbortSignal;
  log?: (message: string) => void;
  concurrency?: number;
}

/**
 * Summarizes research records concurrently into BMW feedback rows matching
 * BMW's feedback export schema (12 columns: ID, Source, Brand, Sales Description,
 * Country, Derivate, Engine Type, Feedback Type, Customer Feedback, Vfc...).
 */
export async function summarizeResearchDataset(
  dataset: ResearchDataset,
  options: SummarizeOptions,
): Promise<ResearchTableRow[]> {
  const sources = new Map(dataset.sources.map((s) => [s.id, s]));
  const concurrency = Math.max(1, Math.min(options.concurrency ?? 4, 8));
  const rows: ResearchTableRow[] = [];

  const summarizedItems = await parallelMap(
    dataset.records,
    concurrency,
    async (record, index) => {
      options.signal.throwIfAborted();
      const source = sources.get(record.sourceId);

      // If the record already has full BMW originalFields, retain it directly.
      const existing = record.metadata.originalFields as Record<string, unknown> | undefined;
      if (
        existing &&
        typeof existing === "object" &&
        existing["Customer Feedback"] &&
        existing["Vfc level2 Name"]
      ) {
        return {
          record,
          source,
          items: [
            {
              brand: String(existing["Brand"] ?? "[BMW]"),
              salesDescription: String(existing["Sales Description"] ?? "[BMW 1 Series]"),
              country: String(existing["Country"] ?? "EU"),
              derivate: String(existing["Derivate (e-code)"] ?? "F70"),
              engineType: (existing["Engine Type"] as SummarizedFeedbackItem["engineType"]) ?? "ICE",
              feedbackType: (existing["Feedback Type"] as SummarizedFeedbackItem["feedbackType"]) ?? "Likes",
              summary: String(existing["Customer Feedback"]),
              vfcLevel2Name: String(existing["Vfc level2 Name"]),
              vfcLevel3Name: String(existing["Vfc level3 Name"] ?? "Like: function"),
            },
          ],
        };
      }

      // Try summarizing via LLM if available and not purely mock/stub
      if (options.llm && typeof options.llm.generateObject === "function") {
        try {
          const prompt = JSON.stringify({
            contract: "reqflow.research.summarize@1",
            scope: {
              vehicleLine: options.scope.vehicleLine,
              vehicleCode: options.scope.vehicleCode,
              derivative: options.scope.derivative,
              market: options.scope.market,
            },
            source: {
              title: source?.title || record.sourceId,
              publisher: source?.publisher,
              url: source?.uri,
              provider: record.provider,
            },
            content: record.text.slice(0, 16_000),
          });

          const result = await options.llm.generateObject({
            schema: SourceSummariesResult,
            system: SUMMARIZER_SYSTEM,
            prompt,
            tier: "fast",
            signal: options.signal,
          });

          if (result && result.object && Array.isArray(result.object.items) && result.object.items.length > 0) {
            return { record, source, items: result.object.items };
          }
        } catch (error) {
          if (options.signal.aborted) throw error;
          options.log?.(
            `Summarizer LLM skipped for record ${record.id} (${error instanceof Error ? error.message : String(error)}); using structured rule-based summary.`,
          );
        }
      }

      // Offline rule-based fallback
      const offlineItem = offlineSummarizeRecord(record, source, options.scope);
      return { record, source, items: [offlineItem] };
    },
    options.signal,
  );

  let seq = 1;
  for (const { record, source, items } of summarizedItems) {
    const columns = Object.fromEntries(BMW_FEEDBACK_HEADERS.map((key) => [key, null]));
    for (const [subIndex, item] of items.entries()) {
      const id = items.length > 1 ? `${record.id}_item${subIndex + 1}` : record.id;
      const vfcFull = `${item.vfcLevel2Name} : ${item.vfcLevel3Name}`;
      const fields: Record<string, unknown> = {
        ...columns,
        ID: id,
        Source: source?.publisher ?? source?.title ?? record.provider,
        Brand: item.brand,
        "Sales Description": item.salesDescription,
        Country: item.country,
        "Derivate (e-code)": item.derivate,
        "Engine Type": item.engineType,
        "Feedback Type": item.feedbackType,
        "Customer Feedback": item.summary,
        "Vfc level2 3 Name": vfcFull,
        "Vfc level2 Name": item.vfcLevel2Name,
        "Vfc level3 Name": item.vfcLevel3Name,
      };

      const row: ResearchTableRow = {
        ...record,
        id,
        collectedRecordId: record.id,
        text: item.summary,
        locator: record.locator,
        fields,
        market: item.country,
        metadata: {
          ...record.metadata,
          originalFields: fields,
        },
        contentHash: createHash("sha256")
          .update(JSON.stringify({ text: item.summary, fields }))
          .digest("hex"),
      };
      rows.push(row);
      seq++;
    }
  }

  return rows;
}

