import { describe, expect, it, vi } from "vitest";
import {
  CollectedItem,
  DEFAULT_SETTINGS,
  ResearchDataset,
  type LlmClient,
  type ProductScope,
} from "@reqflow/core";
import { normalizeItem } from "./raw";
import {
  BMW_FEEDBACK_HEADERS,
  defaultDerivate,
  defaultSalesDescription,
  offlineSummarizeRecord,
  summarizeResearchDataset,
  SummarizedFeedbackItem,
  SourceSummariesResult,
} from "./summarizer";

const at = "2026-10-11T12:00:00.000Z";
const scope: ProductScope = {
  ...DEFAULT_SETTINGS.defaultScope,
  vehicleLine: "1 Series",
  vehicleCode: "F70",
  market: "EU",
};

function createSampleDataset(): ResearchDataset {
  const item1 = CollectedItem.parse({
    provider: "firecrawl",
    sourceId: "source_review_1",
    sourceUrl: "https://auto-review.example.org/bmw-1-series-test",
    sourceTitle: "BMW 120 F70 Extensive Road Test",
    publisher: "Auto Mag",
    recordId: "doc_1",
    recordType: "passage",
    text: "The new BMW 120 F70 handles with exceptional poise and stability in corners. The steering offers great feedback. However, the touchscreen climate controls are frustratingly difficult to use while driving.",
    locator: "test review",
    metadata: {},
  });

  const item2 = CollectedItem.parse({
    provider: "firecrawl",
    sourceId: "source_forum_1",
    sourceUrl: "https://bimmer-forum.example.org/thread/998",
    sourceTitle: "Owner Discussion: M Sport Seats and Mild Hybrid",
    publisher: "Bimmer Forum",
    recordId: "doc_2",
    recordType: "passage",
    text: "The M Sport front seats are very comfortable on 600km road trips, excellent lumbar support. The mild hybrid powertrain provides smooth and instant efficiency.",
    locator: "forum thread",
    metadata: {},
  });

  const { source: s1, record: r1 } = normalizeItem(item1, "editorial_reviews", "run_test", at);
  const { source: s2, record: r2 } = normalizeItem(item2, "owner_forums", "run_test", at);

  return ResearchDataset.parse({
    schemaVersion: 1,
    runId: "run_test",
    retrievedAt: at,
    sources: [s1, s2],
    records: [r1, r2],
    results: [],
    synthetic: true,
  });
}

describe("Research Summarizer", () => {
  it("derives default vehicle identities and sales descriptions", () => {
    expect(defaultDerivate("1 Series")).toBe("F70");
    expect(defaultDerivate("5 Series")).toBe("G60");
    expect(defaultDerivate("7 Series")).toBe("G70");
    expect(defaultSalesDescription("1 Series")).toBe("[BMW 1 Series]");
    expect(defaultSalesDescription("5 Series")).toBe("[BMW 5 Series]");
    expect(defaultSalesDescription("7 Series")).toBe("[BMW 7 Series]");
  });

  it("offline rule-based summarizer extracts categories, sentiment, and detailed summaries", () => {
    const dataset = createSampleDataset();
    const item1 = offlineSummarizeRecord(dataset.records[0]!, dataset.sources[0], scope);

    expect(item1.brand).toBe("[BMW]");
    expect(item1.salesDescription).toBe("[BMW 1 Series]");
    expect(item1.derivate).toBe("F70");
    expect(item1.country).toBe("EU");
    expect(item1.summary).toContain("Auto Mag");
    expect(item1.summary).toContain("poise and stability");
    expect(item1.vfcLevel2Name).toBe("ConnectedDrive and Infotainment, overall technology");
    expect(item1.vfcLevel3Name).toBe("Not user-friendly");
    expect(item1.feedbackType).toBe("Difficult to Use");

    const item2 = offlineSummarizeRecord(dataset.records[1]!, dataset.sources[1], scope);
    expect(item2.feedbackType).toBe("Likes");
    expect(item2.vfcLevel2Name).toBe("Seats");
    expect(item2.vfcLevel3Name).toBe("Likes comfort");
  });

  it("summarizes records in parallel using an LLM client", async () => {
    const dataset = createSampleDataset();
    const generateCalls: unknown[] = [];

    const mockLlm: LlmClient = {
      generateObject: vi.fn(async (req) => {
        generateCalls.push(req);
        return {
          model: "gemini-3.8-flash",
          object: SourceSummariesResult.parse({
            items: [
              {
                brand: "[BMW]",
                salesDescription: "[BMW 1 Series]",
                country: "DE",
                derivate: "F70",
                engineType: "ICE",
                feedbackType: "Likes",
                summary:
                  "Comprehensive assessment: Chassis and steering dynamics receive high praise for precision and feedback. Cornering stability is best-in-class.",
                vfcLevel2Name: "Drive, driving dynamics and chassis, overall technology",
                vfcLevel3Name: "Like: performance",
              },
              {
                brand: "[BMW]",
                salesDescription: "[BMW 1 Series]",
                country: "DE",
                derivate: "F70",
                engineType: "ICE",
                feedbackType: "Difficult to Use",
                summary:
                  "Critical assessment: Touchscreen operation for HVAC and seat heating causes driver distraction and is criticized as awkward on the road.",
                vfcLevel2Name: "Touch screen, operation",
                vfcLevel3Name: "Not user-friendly",
              },
            ],
          }),
        };
      }),
      generateText: vi.fn(),
    };

    const rows = await summarizeResearchDataset(dataset, {
      llm: mockLlm,
      scope,
      signal: new AbortController().signal,
      concurrency: 2,
    });

    expect(mockLlm.generateObject).toHaveBeenCalledTimes(2);
    // 2 records * 2 items each = 4 rows
    expect(rows).toHaveLength(4);

    for (const row of rows) {
      expect(row.fields).toBeDefined();
      for (const header of BMW_FEEDBACK_HEADERS) {
        expect(row.fields[header]).not.toBeUndefined();
      }
      expect(row.fields["Customer Feedback"]).toBe(row.text);
      expect(row.fields["Brand"]).toBe("[BMW]");
      expect(row.fields["Derivate (e-code)"]).toBe("F70");
      expect(row.fields["Vfc level2 3 Name"]).toContain(" : ");
    }

    expect(rows[0]!.fields["Vfc level2 Name"]).toBe(
      "Drive, driving dynamics and chassis, overall technology",
    );
    expect(rows[1]!.fields["Vfc level2 Name"]).toBe("Touch screen, operation");
  });

  it("falls back gracefully to offline summaries when LLM fails or is absent", async () => {
    const dataset = createSampleDataset();
    const failingLlm: LlmClient = {
      generateObject: vi.fn(async () => {
        throw new Error("Provider rate limited");
      }),
      generateText: vi.fn(),
    };

    const logs: string[] = [];
    const rows = await summarizeResearchDataset(dataset, {
      llm: failingLlm,
      scope,
      signal: new AbortController().signal,
      log: (msg) => logs.push(msg),
    });

    expect(rows).toHaveLength(2);
    expect(logs.some((l) => l.includes("using structured rule-based summary"))).toBe(true);
    expect(rows[0]!.fields["Customer Feedback"]).toContain("[Summary]");
    expect(rows[0]!.fields["Derivate (e-code)"]).toBe("F70");
  });

  it("aborts promptly when signal is aborted", async () => {
    const dataset = createSampleDataset();
    const controller = new AbortController();
    controller.abort();

    await expect(
      summarizeResearchDataset(dataset, {
        scope,
        signal: controller.signal,
      }),
    ).rejects.toThrow();
  });
});

