it("parallelMap executes concurrent requests properly using worker pool", async () => {
  let active = 0;
  let maxActive = 0;
  const items = [1, 2, 3, 4, 5, 6, 7, 8];
  const concurrency = 4;

  const results = await parallelMap(
    items,
    concurrency,
    async (val) => {
      active++;
      maxActive = Math.max(maxActive, active);
      await new Promise((resolve) => setTimeout(resolve, 10));
      active--;
      return val * 10;
    },
    new AbortController().signal,
  );

  expect(results).toEqual([10, 20, 30, 40, 50, 60, 70, 80]);
  expect(maxActive).toBeLessThanOrEqual(concurrency);
  expect(maxActive).toBeGreaterThan(1);
});

it("partially failing LLM falls back to offline for failed record without failing whole batch and logs a notice", async () => {
  const dataset = createSampleDataset();
  let callCount = 0;
  const partialLlm: LlmClient = {
    generateObject: vi.fn(async () => {
      callCount++;
      if (callCount === 1) {
        throw new Error("Temporary network timeout");
      }
      return {
        model: "gemini-3.8-flash",
        object: SourceSummariesResult.parse({
          items: [
            {
              brand: "[BMW]",
              salesDescription: "[BMW 1 Series]",
              country: "DE",
              derivate: "F70",
              engineType: "PHEV",
              feedbackType: "Likes",
              summary: "LLM generated high-quality summary for second record.",
              vfcLevel2Name: "Seats",
              vfcLevel3Name: "Likes comfort",
            },
          ],
        }),
      };
    }),
    generateText: vi.fn(),
  };

  const logs: string[] = [];
  const rows = await summarizeResearchDataset(dataset, {
    llm: partialLlm,
    scope,
    signal: new AbortController().signal,
    log: (msg) => logs.push(msg),
  });

  expect(partialLlm.generateObject).toHaveBeenCalledTimes(2);
  expect(rows).toHaveLength(2);

  // Record 1 fell back to rule-based summary
  expect(rows[0]!.fields["Customer Feedback"]).toContain("[Summary]");
  // Record 2 received the LLM summary
  expect(rows[1]!.fields["Customer Feedback"]).toBe("LLM generated high-quality summary for second record.");

  // Notice was logged for the failed record
  expect(
    logs.some(
      (msg) =>
        msg.includes("Summarizer LLM skipped for record") &&
        msg.includes("Temporary network timeout") &&
        msg.includes("using structured rule-based summary"),
    ),
  ).toBe(true);

  // Both rows still have all 12 BMW feedback headers present
  for (const row of rows) {
    for (const header of BMW_FEEDBACK_HEADERS) {
      expect(row.fields[header]).not.toBeUndefined();
      expect(row.fields[header]).not.toBeNull();
    }
  }
});

